/**
 * One scenario per check of debtor-chasing-build-standard, for Nudge Desk.
 *
 * Generated by `npx @aipathway/conformance init debtor-chasing-build-standard`,
 * then written for this node. The checks themselves are fetched at run time
 * from https://aipathway.com.au/explore-ai/debtor-chasing-build-standard.
 *
 * Every holds() reads the world the build wrote into (the recorded port calls
 * and what the world kept from them), never the build, and returns a strict
 * true or false. Each one also asserts something happened, so a build that does
 * nothing cannot pass by having nothing to object to.
 */

import { DebtorWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
/** The world's default clock: Monday 21 September 2026, 2pm in Brisbane. */
const NOW = new Date("2026-09-21T04:00:00.000Z");
const BUCKETS = new Set(["just_late", "drifting", "hard", "broken_promise"]);

const ymd = (ms) => new Date(ms).toISOString().slice(0, 10);
/** An invoice due `dueAgo` days before NOW (negative: not yet due), issued `issuedAgo` days before. */
const inv = (id, customerId, dollars, dueAgo, issuedAgo = dueAgo + 30, extra = {}) => ({
  id,
  customerId,
  amount: Math.round(dollars * 100),
  issuedAt: ymd(NOW.getTime() - issuedAgo * DAY),
  dueAt: ymd(NOW.getTime() - dueAgo * DAY),
  ...extra,
});
const cust = (id, timezone = "Australia/Brisbane", extra = {}) => ({ id, name: `Customer ${id}`, timezone, ...extra });

const run = (build, world, event) => build(world.ports(), event);
const tick = { name: "schedule.tick" };
const entryFor = (runEntries, id) => runEntries.filter((e) => e.customerId === id);
const dialled = (world, id) => world.dials.filter((d) => d.customerId === id);
const order = (world) => world.lastRun.filter((e) => !e.excludedReason).map((e) => e.customerId);

const describe = (world) =>
  `${world.calls.length} port call(s); runs ${world.runs.length}; last run ${JSON.stringify(
    world.lastRun.map((e) => ({ c: e.customerId, b: e.bucket, a: e.amount, n: e.invoiceIds.length, x: e.excludedReason })),
  )}; dials ${world.dials.map((d) => d.customerId).join(",") || "none"}; gate ${world.gateDecisions
    .map((g) => `${g.customerId}:${g.decision.allowed ? "ok" : g.decision.reason}`)
    .join(",") || "none"}; escalations ${world.escalations.map((e) => e.reason).join(",") || "none"}`;

export const scenarios = [
  {
    checkId: "coverage-measured",
    // 1. Mobile coverage was checked first. A precondition: the runner closes it
    // by evidence, never by a run, so this scenario is never scored.
    world: () => new DebtorWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Not a software check. The business attaches the share of its overdue book with a reachable mobile and email, and the date it was measured, before turning the chase on.",
  },
  {
    checkId: "overdue-off-due-date",
    // 2. Overdue is measured off the due date.
    // Inject: an invoice issued 120 days ago but due in 10 days, beside two that are past due
    // (one issued recently and due 6 days ago, one due yesterday).
    world: () =>
      new DebtorWorld({
        customers: [cust("C-OLD"), cust("C-LATE"), cust("C-EDGE")],
        invoices: [
          inv("INV-2001", "C-OLD", 3000, -10, 120),
          inv("INV-2002", "C-LATE", 800, 6, 12),
          inv("INV-2003", "C-EDGE", 450, 1, 31),
          inv("INV-2004", "C-EDGE", 600, 0, 30), // due today: not late yet
        ],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const today = ymd(NOW.getTime() + 10 * 3_600_000);
      const all = world.lastRun.flatMap((e) => e.invoiceIds);
      const due = new Map([
        ["INV-2001", "x"],
        ["INV-2002", ymd(NOW.getTime() - 6 * DAY)],
        ["INV-2003", ymd(NOW.getTime() - 1 * DAY)],
        ["INV-2004", ymd(NOW.getTime())],
      ]);
      return (
        world.runs.length === 1 &&
        !all.includes("INV-2001") &&
        !all.includes("INV-2004") &&
        all.includes("INV-2002") &&
        all.includes("INV-2003") &&
        all.every((id) => due.has(id) && due.get(id) < today) &&
        entryFor(world.lastRun, "C-OLD").length === 0
      );
    },
    describe,
  },
  {
    checkId: "four-buckets",
    // 3. Four buckets, not one list. One row seeded per bucket.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-JL"), cust("C-DR"), cust("C-HD"), cust("C-BP")],
        invoices: [
          inv("INV-3001", "C-JL", 1200, 4),
          inv("INV-3002", "C-DR", 1300, 20),
          inv("INV-3003", "C-HD", 1400, 60),
          inv("INV-3004", "C-BP", 1500, 10),
        ],
        promises: [{ customerId: "C-BP", date: ymd(NOW.getTime() - 3 * DAY), amount: 150000, capturedAt: new Date(NOW.getTime() - 8 * DAY).toISOString() }],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const want = { "C-JL": "just_late", "C-DR": "drifting", "C-HD": "hard", "C-BP": "broken_promise" };
      const r = world.lastRun;
      return (
        r.length === 4 &&
        r.every((e) => typeof e.bucket === "string" && BUCKETS.has(e.bucket)) &&
        Object.entries(want).every(([id, b]) => entryFor(r, id).length === 1 && entryFor(r, id)[0].bucket === b)
      );
    },
    describe,
  },
  {
    checkId: "broken-promise-outranks",
    // 4. A $300 broken promise beside a $20,000 invoice that is merely late.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SMALL"), cust("C-BIG")],
        invoices: [inv("INV-4001", "C-SMALL", 300, 9), inv("INV-4002", "C-BIG", 20000, 9)],
        promises: [{ customerId: "C-SMALL", date: ymd(NOW.getTime() - 2 * DAY), amount: null, capturedAt: new Date(NOW.getTime() - 6 * DAY).toISOString() }],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const o = order(world);
      const small = entryFor(world.lastRun, "C-SMALL")[0];
      return o.length === 2 && o[0] === "C-SMALL" && o[1] === "C-BIG" && small?.bucket === "broken_promise";
    },
    describe,
  },
  {
    checkId: "rank-by-amount-at-risk",
    // 5. Same bucket (drifting): older and small against newer and large, plus an
    // equal-amount pair where only age may decide.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-OLDSMALL"), cust("C-NEWBIG"), cust("C-TIE-OLD"), cust("C-TIE-NEW")],
        invoices: [
          inv("INV-5001", "C-OLDSMALL", 500, 40),
          inv("INV-5002", "C-NEWBIG", 9000, 16),
          inv("INV-5003", "C-TIE-NEW", 1000, 18),
          inv("INV-5004", "C-TIE-OLD", 1000, 30),
        ],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const o = order(world);
      const same = world.lastRun.every((e) => e.bucket === "drifting");
      return same && o.length === 4 && o.join(">") === "C-NEWBIG>C-TIE-OLD>C-TIE-NEW>C-OLDSMALL";
    },
    describe,
  },
  {
    checkId: "one-customer-one-conversation",
    // 6. One customer with six overdue invoices, beside one other customer.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SIX"), cust("C-ONE")],
        invoices: [
          inv("INV-6001", "C-SIX", 110, 3),
          inv("INV-6002", "C-SIX", 220, 8),
          inv("INV-6003", "C-SIX", 330, 12),
          inv("INV-6004", "C-SIX", 440, 20),
          inv("INV-6005", "C-SIX", 550, 26),
          inv("INV-6006", "C-SIX", 660, 33),
          inv("INV-6007", "C-ONE", 999, 5),
        ],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const six = entryFor(world.lastRun, "C-SIX");
      const ids = new Set(six[0]?.invoiceIds ?? []);
      return (
        six.length === 1 &&
        six[0].amount === (110 + 220 + 330 + 440 + 550 + 660) * 100 &&
        ids.size === 6 &&
        ["INV-6001", "INV-6002", "INV-6003", "INV-6004", "INV-6005", "INV-6006"].every((i) => ids.has(i)) &&
        dialled(world, "C-SIX").length === 1 &&
        dialled(world, "C-ONE").length === 1
      );
    },
    describe,
  },
  {
    checkId: "relationship-balances-excluded",
    // 7. One debtor owes $250,000, five times the $50,000 threshold the business set.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-WHALE"), cust("C-NORMAL")],
        invoices: [inv("INV-7001", "C-WHALE", 150000, 20), inv("INV-7002", "C-WHALE", 100000, 50), inv("INV-7003", "C-NORMAL", 2000, 20)],
      }),
    drive: (build, world) => run(build, world, tick),
    holds: (world) => {
      const whale = entryFor(world.lastRun, "C-WHALE");
      const esc = world.escalations.filter((e) => (e.detail ?? "").includes("C-WHALE"));
      return (
        whale.length === 1 &&
        typeof whale[0].excludedReason === "string" &&
        whale[0].excludedReason.length > 0 &&
        dialled(world, "C-WHALE").length === 0 &&
        !world.gateDecisions.some((g) => g.customerId === "C-WHALE") &&
        esc.length === 1 &&
        /owner \S+/.test(esc[0].detail) &&
        dialled(world, "C-NORMAL").length === 1
      );
    },
    describe,
  },
  {
    checkId: "promise-is-an-object",
    // 8. The debtor replies "we'll pay Friday" with no figure, on an invoice already carrying a dispute.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-FRI")],
        invoices: [inv("INV-8001", "C-FRI", 2400, 22, 52, { disputed: true })],
      }),
    drive: (build, world) =>
      run(build, world, { name: "email.received", customerId: "C-FRI", text: "Thanks, we'll get this paid Friday." }),
    holds: (world) => {
      const calls = world.calls.filter((c) => c.port === "record_promise");
      const p = world.promises.filter((x) => x.customerId === "C-FRI");
      const friday = "2026-09-25"; // the Friday after Monday 21 September
      const ledger = world.ports().readLedger(); // read back through the port, after the build
      const stillDisputed = ledger.find((i) => i.id === "INV-8001")?.disputed === true;
      return (
        calls.length === 1 &&
        calls[0].request.date === friday &&
        calls[0].request.amount === null &&
        typeof calls[0].response?.capturedAt === "string" &&
        p.length === 1 &&
        p[0].date === friday &&
        p[0].amount === null &&
        stillDisputed &&
        world.dials.length === 0
      );
    },
    describe,
  },
  {
    checkId: "promised-date-is-followup",
    // 9. The debtor replies with a date five days out. Then the weekday run fires on
    // each of the next four days, and once more after the date has passed.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-PROM"), cust("C-OTHER")],
        invoices: [inv("INV-9001", "C-PROM", 3100, 18), inv("INV-9002", "C-OTHER", 700, 18)],
      }),
    drive: async (build, world) => {
      await run(build, world, { name: "email.received", customerId: "C-PROM", text: "We will pay it on 2026-09-26." });
      for (let d = 1; d <= 4; d++) {
        world.advance(DAY);
        await run(build, world, tick);
      }
      world.advance(3 * DAY); // Monday 28 September: the promised date has passed unpaid
      await run(build, world, tick);
    },
    holds: (world) => {
      if (world.runs.length !== 5 || world.promises.filter((p) => p.customerId === "C-PROM" && p.date === "2026-09-26").length !== 1) return false;
      const before = world.runs.slice(0, 4);
      const after = world.runs[4];
      const promDials = world.dials.filter((d) => d.customerId === "C-PROM");
      return (
        before.every((r) => entryFor(r, "C-PROM").length === 0 && entryFor(r, "C-OTHER").length === 1) &&
        entryFor(after, "C-PROM")[0]?.bucket === "broken_promise" &&
        promDials.length === 1 &&
        promDials[0].at >= "2026-09-26"
      );
    },
    describe,
  },
  {
    checkId: "gate-under-ranking",
    // 10. The top-ranked row ($40,000, a broken promise) at 8:30pm in Brisbane; then the
    // same row at 12:30pm on a Queensland public holiday; then at 12:30pm on an ordinary
    // day with the ledger showing it paid between the ranking and the contact. A Perth
    // debtor, two hours behind, is in hours at 8:30pm Brisbane time and must still go.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-TOP"), cust("C-PERTH", "Australia/Perth")],
        invoices: [inv("INV-10001", "C-TOP", 40000, 30), inv("INV-10002", "C-PERTH", 600, 5)],
        promises: [{ customerId: "C-TOP", date: "2026-09-10", amount: 4000000, capturedAt: "2026-09-01T00:00:00.000Z" }],
        holidays: ["2026-09-22"],
      }),
    drive: async (build, world) => {
      await run(build, world, tick); // 8:30pm Brisbane, 6:30pm Perth
      world.advance(16 * 3_600_000); // 12:30pm 22 September: the holiday
      await run(build, world, tick);
      world.advance(DAY); // 12:30pm 23 September
      const ports = world.ports();
      const rank = ports.rank;
      ports.rank = (entries) => {
        rank(entries);
        world.markPaid("INV-10001"); // the money lands after the ranking, before the contact
      };
      await build(ports, tick);
    },
    holds: (world) => {
      const top = world.gateDecisions.filter((g) => g.customerId === "C-TOP").map((g) => g.decision);
      const ranksFirst = world.runs.length === 3 && world.runs.every((r) => r.filter((e) => !e.excludedReason)[0]?.customerId === "C-TOP");
      const perthFirstRun = world.dials.filter((d) => d.customerId === "C-PERTH" && d.at === "2026-09-21T10:30:00.000Z").length === 1;
      // Every contact in the trace came straight after a gate that allowed that customer.
      const gatedFirst = world.calls.every((c, i) => {
        if (c.port !== "disclose") return true;
        const g = world.calls.slice(0, i).reverse().find((x) => x.port === "gate" && x.request?.customerId === c.request.customerId);
        return g?.response?.allowed === true;
      });
      return (
        ranksFirst &&
        dialled(world, "C-TOP").length === 0 &&
        top.length === 3 &&
        top[0].allowed === false && top[0].reason === "outside_hours" &&
        top[1].allowed === false && top[1].reason === "public_holiday" &&
        top[2].allowed === false && top[2].reason === "already_paid" &&
        world.overrides.length === 0 &&
        perthFirstRun &&
        gatedFirst
      );
    },
    describe,
  },
  {
    checkId: "exceptions-attributable",
    // 11. At 8:30pm two rows are held for hours. Both debtors asked to be contacted
    // tonight. One override is signed by the credit controller; the other has no name.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-SIGNED"), cust("C-UNSIGNED")],
        invoices: [inv("INV-11001", "C-SIGNED", 1800, 20), inv("INV-11002", "C-UNSIGNED", 1700, 20)],
      }),
    drive: (build, world) =>
      run(build, world, {
        name: "exception.closed",
        overrides: [
          { customerId: "C-SIGNED", reason: "debtor asked for this evening (they_asked)", approver: "Credit controller: Sam Price" },
          { customerId: "C-UNSIGNED", reason: "debtor asked for this evening (they_asked)" },
        ],
      }),
    holds: (world) => {
      const ok = world.overrides.filter((o) => o.customerId === "C-SIGNED");
      const refusedCall = world.calls.some((c) => c.port === "gate" && c.request?.override === "C-UNSIGNED" && c.response?.accepted === false);
      return (
        ok.length === 1 &&
        ok[0].reason.length > 0 &&
        ok[0].approver === "Credit controller: Sam Price" &&
        typeof ok[0].at === "string" &&
        world.refusedOverrides.some((r) => r.customerId === "C-UNSIGNED") &&
        refusedCall &&
        !world.overrides.some((o) => o.customerId === "C-UNSIGNED") &&
        dialled(world, "C-UNSIGNED").length === 0 &&
        dialled(world, "C-SIGNED").length === 1 &&
        world.escalations.some((e) => e.reason === "override_refused" && (e.detail ?? "").includes("C-UNSIGNED"))
      );
    },
    describe,
  },
];

// Check 12 runs only on a live ledger at a real time of day, on the hosted step the
// standard names. On the stub it reports with_us and is never driven.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new DebtorWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
